from collections import deque
g = {'A': ['B', 'C'], 'B': ['D'], 'C': ['E'], 'D': [], 'E': []}
def bfs(s):
    vis, f, o = set(), deque([s]), []
    while f:
        v = f.popleft()
        if v not in vis: vis.add(v); o.append(v); f.extend(g[v])
    return o
def dfs(v, vis=None, o=None):
    vis = set() if vis is None else vis; o = [] if o is None else o
    vis.add(v); o.append(v)
    for w in g[v]:
        if w not in vis: dfs(w, vis, o)
    return o
print('BFS', bfs('A'), 'DFS', dfs('A'))

